package br.com.dio.Modelo;import java.util.Collection;import java.util.List;import static br.com.dio.Modelo.GamestartEnum.*;import static java.util.Objects.isNull;import static java.util.Objects.nonNull;public class Board {    private final List<List<Space>> spaces;    public Board(List<List<Space>> spaces) {        this.spaces = spaces;    }    public List<List<Space>> getSpaces() {        return spaces;    }    public GamestartEnum getStatus() {        if (spaces.stream().flatMap(Collection::stream).noneMatch(e -> !e.isFixed() && nonNull(e.getActual()))) {            return NO_STARTING;        }        return spaces.stream().flatMap(Collection::stream).anyMatch(e -> isNull(e.getActual())) ? INCOMPLETE : COMPLETE;    }    public boolean hasError() {        if (getStatus() == NO_STARTING) {            return false;        }        return spaces.stream().flatMap(Collection::stream)                .anyMatch(e -> nonNull(e.getActual()) && !e.getActual().equals(e.getExpected()));    }    public boolean changeValue(final int col, final int row, final int value) {        var space = spaces.get(row).get(col);        if (space.isFixed()) {            return false;        }        space.setActual(value);        return true;    }    public boolean clearValue(final int col, final int row) {        var space = spaces.get(col).get(row);        if (space.isFixed()) {            return false;        }        space.Clearspace();        return true;    }    public void reset() {        spaces.forEach(s -> s.forEach(Space::Clearspace));    }    public boolean gameIsFinished() {        return !hasError() && getStatus() == GamestartEnum.COMPLETE;    }}